"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes the syntax; where it is silent or wrong,
the behaviour below follows what `packignore` actually did.
"""

import os
import re


def _compile_segment(seg):
    # Only `*` (any run within a segment) and `?` (one character) are special;
    # `[`, `\` and everything else are literal. `**` inside a segment is `*`.
    parts = []
    for ch in seg:
        if ch == "*":
            if not parts or parts[-1] != "[^/]*":
                parts.append("[^/]*")
        elif ch == "?":
            parts.append("[^/]")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


class _Rule:
    def __init__(self, base, negated, dir_only, anchored, segments):
        self.base = base            # tuple of path components of the .packignore's directory
        self.negated = negated
        self.dir_only = dir_only
        self.anchored = anchored
        # A whole segment of `**` matches zero or more path components.
        self.segments = [None if s == "**" else _compile_segment(s) for s in segments]

    def matches(self, parts, is_dir):
        if self.dir_only and not is_dir:
            return False
        n = len(self.base)
        if len(parts) <= n or tuple(parts[:n]) != self.base:
            return False
        rel = parts[n:]
        if not self.anchored:
            seg = self.segments[0]
            return seg is None or seg.fullmatch(rel[-1]) is not None
        return _match_segments(self.segments, rel)


def _match_segments(segs, parts):
    # Classic glob backtracking over path components.
    memo = {}

    def go(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(segs):
            res = j == len(parts)
        elif segs[i] is None:
            res = any(go(i + 1, k) for k in range(j, len(parts) + 1))
        else:
            res = j < len(parts) and segs[i].fullmatch(parts[j]) is not None and go(i + 1, j + 1)
        memo[key] = res
        return res

    return go(0, 0)


def _parse(text, base):
    rules = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        negated = line.startswith("!")
        if negated:
            line = line[1:]
        dir_only = line.endswith("/")
        line = line.rstrip("/")
        anchored = "/" in line
        if line.startswith("/"):
            line = line[1:]
        if not line:
            continue
        rules.append(_Rule(base, negated, dir_only, anchored, line.split("/")))
    return rules


def _status(rules, parts, is_dir, inherited):
    for rule in reversed(rules):
        if rule.matches(parts, is_dir):
            return not rule.negated
    return inherited


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    ignored = []

    def walk(path, parts, rules, excluded):
        names = sorted(os.listdir(path))
        if not parts and ".git" in names and os.path.isdir(os.path.join(path, ".git")):
            names.remove(".git")
        if not excluded and ".packignore" in names:
            full = os.path.join(path, ".packignore")
            if os.path.isfile(full):
                with open(full, newline="") as f:
                    rules = rules + _parse(f.read(), tuple(parts))
        for name in names:
            full = os.path.join(path, name)
            child = parts + [name]
            if os.path.isdir(full):
                walk(full, child, rules, _status(rules, child, True, excluded))
            elif _status(rules, child, False, excluded):
                ignored.append("/".join(child))

    walk(root, [], [], False)
    return sorted(ignored)

