    # Classic glob backtracking over path components.
    memo = {}

    def go(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(segs):
            res = j == len(parts)
        elif segs[i] is None:
            res = any(go(i + 1, k) for k in range(j, len(parts) + 1))
        else:
            res = j < len(parts) and segs[i].fullmatch(parts[j]) is not None and go(i + 1, j + 1)
        memo[key] = res
        return res

    return go(0, 0)


def _parse(text, base):
    rules = []
