    """Whether `parts` is excluded; with no matching rule it inherits its parent's status."""
    best = None
    for rule in rules:
        if rule.matches(parts, is_dir) and (best is None or rule.priority > best.priority):
            best = rule
    return inherited if best is None else not best.negated


