import os
import re


def _compile_segment(seg):
    # Only `*` (any run within a segment) and `?` (one character) are special;
    # `[`, `\` and everything else are literal. `**` inside a segment is `*`.
    parts = []
    for ch in seg:
        if ch == "*":
            if not parts or parts[-1] != "[^/]*":
                parts.append("[^/]*")
        elif ch == "?":
            parts.append("[^/]")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


class _Rule:
    def __init__(self, negated, dir_only, anchored, segments, index):
        self.negated = negated
        self.dir_only = dir_only
        self.anchored = anchored
        # A whole segment of `**` matches zero or more path components.
        self.segments = [None if s == "**" else _compile_segment(s) for s in segments]
        # When several rules in one file match the same path, the one with the
        # most literal (non-wildcard) characters wins; ties go to the later line.
        self.priority = (sum(len(s) - s.count("*") - s.count("?") for s in segments), index)

    def matches(self, rel, is_dir):
        """Whether the rule matches `rel`, a path relative to its .packignore's directory."""
        if self.dir_only and not is_dir:
            return False
        if not self.anchored:
            seg = self.segments[0]
            return seg is None or seg.fullmatch(rel[-1]) is not None
        return _match_segments(self.segments, rel)


def _match_segments(segs, parts):
    # Classic glob backtracking over path components.
    memo = {}

    def go(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(segs):
            res = j == len(parts)
        elif segs[i] is None:
            res = any(go(i + 1, k) for k in range(j, len(parts) + 1))
        else:
            res = j < len(parts) and segs[i].fullmatch(parts[j]) is not None and go(i + 1, j + 1)
        memo[key] = res
        return res

    return go(0, 0)


def _parse(text):
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        negated = line.startswith("!")
        if negated:
            line = line[1:]
        dir_only = line.endswith("/")
        line = line.rstrip("/")
        anchored = "/" in line
        line = line.lstrip("/")
        if not line:
            continue
        rules.append(_Rule(negated, dir_only, anchored, line.split("/"), len(rules)))
    return rules


def _verdict(rules, rel, is_dir):
    """True/False if some rule matches `rel` (excluded or re-included), else None."""
    best = None
    for rule in rules:
        if rule.matches(rel, is_dir) and (best is None or rule.priority > best.priority):
