                if not e.is_symlink():
                    walk(e.path, child, layers, child_states(layers, states, child, True))
            elif excluded(child_states(layers, states, child, False)):
                ignored.append("/".join(child))

    walk(root, [], [], [])
    return sorted(ignored)

